                        <p>{hourlyResults?.days[0].sunset} PM</p>
                    </div>
                    <div className="card">
                        <p>HUMIDITY</p>
                        <p>{hourlyResults?.days[0].humidity}</p>
                    </div>
                    <div className="card">
                        <p>PRECIPITATION</p>
                        <p>{precipitation}</p>
                    </div>
                    <div className="card">
                        <p>WIND</p>
                        <p>{windSpeed}</p>
                    </div>
                </div>


            </>
        );
    }


